import base64
import io
import re
from collections import Counter
import matplotlib.pyplot as plt

def fig_to_base64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight')
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# Read data
df = pd.read_csv('/app/benchmark/data.csv')

# 1. Dataset & Examination Overview
total_questions = len(df)
min_year = df['year'].min()
max_year = df['year'].max()
type_counts = df['type'].value_counts()

# 2. Year-by-Year Question Volume Analysis
yearly_counts = df.groupby('year').size()
fig1, ax1 = plt.subplots(figsize=(10, 5))
yearly_counts.plot(kind='line', marker='o', ax=ax1, color='#2c3e50')
ax1.set_title('Total Questions per Year (2015-2025)')
ax1.set_xlabel('Year')
ax1.set_ylabel('Total Questions')
ax1.grid(True, linestyle='--', alpha=0.7)
ax1.set_xticks(range(int(min_year), int(max_year)+1))
yearly_trend_img = fig_to_base64(fig1)

# 3. Question Type Composition & Trends
yearly_type_counts = df.groupby(['year', 'type']).size().unstack(fill_value=0)
fig2, ax2 = plt.subplots(figsize=(10, 6))
yearly_type_counts.plot(kind='bar', stacked=True, ax=ax2, colormap='viridis')
ax2.set_title('Question Type Composition per Year')
ax2.set_xlabel('Year')
ax2.set_ylabel('Number of Questions')
ax2.legend(title='Question Type')
ax2.grid(axis='y', linestyle='--', alpha=0.7)
type_trend_img = fig_to_base64(fig2)

# Type ratios
yearly_type_ratios = yearly_type_counts.div(yearly_type_counts.sum(axis=1), axis=0) * 100
fig3, ax3 = plt.subplots(figsize=(10, 6))
yearly_type_ratios.plot(kind='bar', stacked=True, ax=ax3, colormap='magma')
ax3.set_title('Question Type Ratio per Year (%)')
ax3.set_xlabel('Year')
ax3.set_ylabel('Percentage (%)')
ax3.legend(title='Question Type', loc='center left', bbox_to_anchor=(1, 0.5))
ax3.grid(axis='y', linestyle='--', alpha=0.7)
type_ratio_img = fig_to_base64(fig3)

# 4. Recurring Topics & Question Content Patterns
def extract_keywords(text):
    text = text.lower()
    text = text.replace('$', ' ')
    words = re.findall(r'\b[a-z]{3,}\b', text)
    stop_words = {'the', 'and', 'what', 'define', 'explain', 'write', 'is', 'of', 'in', 'are', 'to', 'for', 'with', 'an', 'this', 'that', 'it', 'on', 'by', 'as', 'or', 'be', 'how', 'which', 'from', 'can', 'has', 'used', 'program', 'example', 'statement', 'following', 'language'}
    return [w for w in words if w not in stop_words]

all_keywords = []
for q in df['question']:
    all_keywords.extend(extract_keywords(q))

keyword_counts = Counter(all_keywords).most_common(20)

fig4, ax4 = plt.subplots(figsize=(10, 6))
keywords, counts = zip(*keyword_counts)
ax4.barh(keywords, counts, color='#3498db')
ax4.invert_yaxis()
ax4.set_title('Top 20 Most Frequent Keywords in Questions')
ax4.set_xlabel('Frequency')
keyword_img = fig_to_base64(fig4)

